package com.smarthub.plus;
import android.content.Context;import org.json.*;import java.time.*;import java.util.*;import java.io.*;
/** Public documented v1 shared key 123 is not a private credential. Free tier is explicitly limited. */
final class TheSportsDBProvider implements SportsDataProvider {
 static final String API="https://www.thesportsdb.com/api/v1/json/123/";private final Context context;private final SportsCache cache;
 TheSportsDBProvider(Context c){context=c.getApplicationContext();cache=new SportsCache(c);}
 public String name(){return "TheSportsDB · free limited schedules";}
 JSONObject league(LeagueRepository.League l)throws Exception{if(l.id.isEmpty())throw new IOException("No verified TheSportsDB league ID");JSONObject wrapper=cache.get(API+"lookupleague.php?id="+l.id,7*86400000L);JSONArray a=wrapper.getJSONObject("data").optJSONArray("leagues");JSONObject row=a==null?null:a.optJSONObject(0);if(row==null||!l.id.equals(row.optString("idLeague"))||!"Soccer".equals(row.optString("strSport"))||!LeagueRepository.nameMatches(l,row.optString("strLeague")))throw new IOException("League identity could not be verified");return row;}
 public List<SportsMatch> matches(LeagueRepository.League l,LocalDate day,String window)throws Exception{JSONObject metadata=league(l);String route=window.equals("next")?"eventsnextleague.php?id="+l.id:window.equals("past")?"eventspastleague.php?id="+l.id:"eventsday.php?d="+day+"&s=Soccer&l="+l.id;JSONObject wrapper=cache.get(API+route,window.equals("day")?120000L:15*60000L);JSONArray rows=wrapper.getJSONObject("data").optJSONArray("events");List<SportsMatch> out=new ArrayList<>();if(rows!=null)for(int i=0;i<rows.length();i++){SportsMatch m=parse(rows.optJSONObject(i),l,wrapper.optLong("at"),wrapper.optBoolean("stale"));if(m!=null){if(m.leagueLogo.isEmpty())m.leagueLogo=metadata.optString("strBadge");out.add(m);}}return out;}
 static SportsMatch parse(JSONObject j,LeagueRepository.League l,long at,boolean stale){if(j==null||!l.id.equals(j.optString("idLeague"))||!j.optString("strSport","Soccer").equals("Soccer")||!j.optString("idEvent").matches("[0-9]+")||j.optString("strHomeTeam").isEmpty()||j.optString("strAwayTeam").isEmpty())return null;SportsMatch m=new SportsMatch();m.id="tsdb:"+j.optString("idEvent");m.leagueId=l.id;m.league=l.name;m.home=j.optString("strHomeTeam");m.away=j.optString("strAwayTeam");m.homeId=j.optString("idHomeTeam");m.awayId=j.optString("idAwayTeam");m.homeLogo=j.optString("strHomeTeamBadge","");m.awayLogo=j.optString("strAwayTeamBadge","");m.leagueLogo=j.optString("strLeagueBadge","");m.image=j.optString("strPoster","");if(m.image.isEmpty())m.image=j.optString("strThumb","");m.homeScore=number(j,"intHomeScore");m.awayScore=number(j,"intAwayScore");m.status=j.optString("strStatus","UNKNOWN");if(m.status.isEmpty())m.status="UNKNOWN";m.minute=j.optString("strProgress","");m.venue=j.optString("strVenue","");m.description=j.optString("strDescriptionEN","");String timestamp=j.optString("strTimestamp","");if(timestamp.isEmpty()&&!j.optString("strTime").isEmpty())timestamp=j.optString("dateEvent")+"T"+j.optString("strTime");m.kickoff=SportsMatch.utc(timestamp);m.updatedAt=at;m.cached=stale;m.source="TheSportsDB · free: up to 3/day; next/past 1 · not a live feed";return m;}
 private static String number(JSONObject j,String k){if(j.isNull(k))return "";String v=j.optString(k);return v.matches("[0-9]{1,3}")?v:"";}
 JSONObject details(String id,String endpoint)throws Exception{if(!id.matches("tsdb:[0-9]+"))throw new IOException("Details not supplied by this source");if(!Arrays.asList("lookupevent","lookuptimeline","lookuplineup","lookupeventstats").contains(endpoint))throw new IOException("Unsupported details endpoint");return cache.get(API+endpoint+".php?id="+id.substring(5),5*60000L);}
}
